import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import type { NestExpressApplication } from '@nestjs/platform-express';
import pg from 'pg';
import request from 'supertest';
import { createApp } from '../../src/app.js';
import { JsonLogger } from '../../src/common/logger.js';
import { type AppConfig, loadConfig } from '../../src/config/env.js';

export const ORIGIN = 'http://localhost:3210';

/** Reads apps/api/.env (generated by `pnpm setup`) without touching process.env. */
export function fileEnv(): Record<string, string> {
  const file = fileURLToPath(new URL('../../.env', import.meta.url));
  if (!existsSync(file)) throw new Error('apps/api/.env missing — run `pnpm setup` first.');
  const out: Record<string, string> = {};
  for (const line of readFileSync(file, 'utf8').split(/\r?\n/)) {
    const m = /^([A-Z0-9_]+)=(.*)$/.exec(line);
    if (m) out[m[1]!] = m[2]!;
  }
  return out;
}

export function testEnv(overrides: Record<string, string> = {}): Record<string, string> {
  const f = fileEnv();
  if (!f.TEST_DATABASE_URL || !f.TEST_MIGRATION_DATABASE_URL) throw new Error('TEST_DATABASE_URL / TEST_MIGRATION_DATABASE_URL missing');
  return {
    ...f,
    APP_ENV: 'test',
    DATABASE_URL: f.TEST_DATABASE_URL,
    MIGRATION_DATABASE_URL: f.TEST_MIGRATION_DATABASE_URL,
    AUTH_MFA_REQUIRED: 'false',
    LOGIN_RATE_LIMIT_PER_MINUTE: '1000',
    RATE_LIMIT_PER_MINUTE: '10000',
    LOG_LEVEL: 'error',
    OPENAPI_ENABLED: 'false',
    // The agent gateway listener is started only by tests that need it (port per test).
    AGENT_GATEWAY_ENABLED: 'false',
    ...overrides,
  };
}

export function testConfig(overrides: Record<string, string> = {}): AppConfig {
  return loadConfig(testEnv(overrides));
}

export const PASSWORD = () => fileEnv().SEED_DEFAULT_PASSWORD!;

export async function startApp(overrides: Record<string, string> = {}): Promise<NestExpressApplication> {
  // Rate limits are resolved lazily from process.env (see config/rate-limits.ts).
  process.env.LOGIN_RATE_LIMIT_PER_MINUTE = overrides.LOGIN_RATE_LIMIT_PER_MINUTE ?? '1000';
  process.env.RATE_LIMIT_PER_MINUTE = overrides.RATE_LIMIT_PER_MINUTE ?? '10000';
  const app = await createApp(testConfig(overrides), { logger: new JsonLogger('error', () => undefined) });
  await app.init();
  return app;
}

/** Cookie-aware API client that behaves like the browser UI (Origin + CSRF header on mutations). */
export class Client {
  cookies = new Map<string, string>();
  constructor(private readonly app: NestExpressApplication, private readonly origin = ORIGIN) {}

  private absorb(res: request.Response) {
    const set = res.headers['set-cookie'] as unknown as string[] | undefined;
    for (const c of set ?? []) {
      const [kv] = c.split(';');
      const i = kv!.indexOf('=');
      const name = kv!.slice(0, i);
      const value = kv!.slice(i + 1);
      if (!value || /expires=Thu, 01 Jan 1970/i.test(c)) this.cookies.delete(name);
      else this.cookies.set(name, value);
    }
    return res;
  }

  get cookieHeader() {
    return [...this.cookies].map(([k, v]) => `${k}=${v}`).join('; ');
  }

  async get(path: string) {
    return this.absorb(await request(this.app.getHttpServer()).get(`/api/v1${path}`).set('cookie', this.cookieHeader));
  }

  async send(method: 'post' | 'patch' | 'put' | 'delete', path: string, body?: unknown, opts: { csrf?: string | null; origin?: string | null } = {}) {
    let r = request(this.app.getHttpServer())[method](`/api/v1${path}`).set('cookie', this.cookieHeader);
    const origin = opts.origin === undefined ? this.origin : opts.origin;
    if (origin) r = r.set('origin', origin);
    const csrf = opts.csrf === undefined ? this.cookies.get('psacc_csrf') : opts.csrf;
    if (csrf) r = r.set('x-csrf-token', csrf);
    return this.absorb(await (body === undefined ? r : r.send(body as object)));
  }

  post(path: string, body?: unknown, opts?: { csrf?: string | null; origin?: string | null }) {
    return this.send('post', path, body, opts);
  }
  patch(path: string, body?: unknown, opts?: { csrf?: string | null; origin?: string | null }) {
    return this.send('patch', path, body, opts);
  }
  put(path: string, body?: unknown) {
    return this.send('put', path, body);
  }
  del(path: string, body?: unknown) {
    return this.send('delete', path, body);
  }

  async login(email: string, password = PASSWORD()) {
    return this.post('/auth/login', { email, password });
  }
}

export async function signedIn(app: NestExpressApplication, email: string, password?: string): Promise<Client> {
  const c = new Client(app);
  const r = await c.login(email, password);
  if (r.status !== 200) throw new Error(`login failed for ${email}: ${r.status} ${JSON.stringify(r.body)}`);
  return c;
}

/** Schema-owner connection (bypasses nothing it shouldn't: FORCE RLS tables still need context). */
export async function ownerQuery<T = Record<string, unknown>>(sql: string, params: unknown[] = []): Promise<T[]> {
  const client = new pg.Client({ connectionString: testEnv().MIGRATION_DATABASE_URL });
  await client.connect();
  try {
    return (await client.query(sql, params)).rows as T[];
  } finally {
    await client.end();
  }
}

/**
 * Runs statements as the application role (psacc_app) inside one transaction with the given
 * tenant context — exactly how the API accesses data. Rolled back afterwards.
 */
export async function asApp<T>(ctx: { orgId?: string; userId?: string; scopeAll?: boolean } | null, fn: (c: pg.Client) => Promise<T>): Promise<T> {
  const client = new pg.Client({ connectionString: testEnv().DATABASE_URL });
  await client.connect();
  try {
    await client.query('BEGIN');
    if (ctx) {
      await client.query(`SELECT set_config('app.org_id', $1, true), set_config('app.user_id', $2, true), set_config('app.scope_all', $3, true)`, [
        ctx.orgId ?? '',
        ctx.userId ?? '',
        ctx.scopeAll ? 'on' : 'off',
      ]);
    }
    return await fn(client);
  } finally {
    await client.query('ROLLBACK').catch(() => undefined);
    await client.end();
  }
}

/** Like asApp, but commits: for tests that must change state behind the API (e.g. simulate time passing). */
export async function asAppCommit<T>(ctx: { orgId: string; scopeAll?: boolean }, fn: (c: pg.Client) => Promise<T>): Promise<T> {
  const client = new pg.Client({ connectionString: testEnv().DATABASE_URL });
  await client.connect();
  try {
    await client.query('BEGIN');
    await client.query(`SELECT set_config('app.org_id', $1, true), set_config('app.scope_all', $2, true)`, [ctx.orgId, ctx.scopeAll === false ? 'off' : 'on']);
    const out = await fn(client);
    await client.query('COMMIT');
    return out;
  } catch (err) {
    await client.query('ROLLBACK').catch(() => undefined);
    throw err;
  } finally {
    await client.end();
  }
}

export async function ids() {
  const [a] = await ownerQuery<{ id: string }>(`SELECT id FROM organizations WHERE slug = 'psacc-dev'`);
  const [b] = await ownerQuery<{ id: string }>(`SELECT id FROM organizations WHERE slug = 'isolation-org-b'`);
  const users = await ownerQuery<{ id: string; email: string }>('SELECT id, email FROM users');
  const byEmail = Object.fromEntries(users.map((u) => [u.email, u.id]));
  return { orgA: a!.id, orgB: b!.id, user: (email: string) => byEmail[email]! };
}

/** Live count of organization A clients (other test files may onboard new clients). */
export async function orgAClientCount(): Promise<number> {
  const { orgA } = await ids();
  return asApp({ orgId: orgA, scopeAll: true }, async (c) => (await c.query('SELECT count(*)::int AS n FROM clients')).rows[0].n as number);
}

